CREATE TABLE ai_capability(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,name VARCHAR(128) NOT NULL,version VARCHAR(32) NOT NULL,enabled BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_ai_capability_tenant_name UNIQUE(tenant_id,name));
CREATE TABLE ai_plugin(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,name VARCHAR(128) NOT NULL,version VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,descriptor JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_ai_plugin_tenant_name UNIQUE(tenant_id,name));
CREATE TABLE ai_policy(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,name VARCHAR(128) NOT NULL,classification VARCHAR(64) NOT NULL,policy_json JSONB NOT NULL,enabled BOOLEAN NOT NULL,version INT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE ai_context_cache(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,cache_key VARCHAR(256) NOT NULL,context_json JSONB NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_ai_cache_tenant_key UNIQUE(tenant_id,cache_key));
CREATE TABLE ai_execution_pipeline(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,session_id UUID,capability_id UUID,plugin_id UUID,tool_id UUID,status VARCHAR(32) NOT NULL,correlation_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_ai_capability_tenant ON ai_capability(tenant_id,enabled);CREATE INDEX idx_ai_plugin_tenant ON ai_plugin(tenant_id,status);CREATE INDEX idx_ai_cache_expiry ON ai_context_cache(tenant_id,expires_at);
